const { execFile } = require('child_process');
const util = require('util');
const execFilePromise = util.promisify(execFile);

async function concatenatePDFs(inputFiles, outputFilePath) {
  try {
    await execFilePromise('pdfunite', [...inputFiles, outputFilePath]);
    console.log('PDFs concatenated successfully');
  } catch (error) {
    console.error('Error concatenating PDFs:', error);
  }
}

// Example usage
concatenatePDFs(['file1.pdf', 'file2.pdf'], 'concatenated.pdf');

